
CREATE TABLE "FASTSQLORDER" ("ID" INT IDENTITY(1,1) NOT NULL, "CUSTOMERNAME" VARCHAR(64) NULL, "CUSTOMERID" INT NOT NULL, "AMOUNT" NUMERIC(18,4) NOT NULL, "STATE" INT NOT NULL, "CREATEDAT" DATETIME(3) NOT NULL, "PAIDAT" DATETIME(3) NULL, "NOTE" TEXT NULL, CONSTRAINT "PK_FASTSQLORDER" PRIMARY KEY ("ID")) ; CREATE INDEX "IX_FASTSQLORDER_CREATEDAT" ON "FASTSQLORDER" ( "CREATEDAT" ASC )
